import json, os, subprocess, tempfile
from pathlib import Path

def git(args, env):
    return subprocess.run(['git', *args],env=env,capture_output=True,text=True,check=True).stdout.strip()
with tempfile.TemporaryDirectory() as d:
    clean={k:v for k,v in os.environ.items() if not k.startswith('GIT_')}
    parent, child=Path(d)/'parent',Path(d)/'child'
    for p in [parent,child]:
        git(['init','-q',str(p)],clean)
        git(['-C',str(p),'config','demo.marker','before'],clean)
    inherited=dict(clean,GIT_DIR=str(parent/'.git'))
    git(['-C',str(child),'config','demo.marker','after'],inherited)
    print(json.dumps({p.name:git(['-C',str(p),'config','demo.marker'],clean) for p in [parent,child]}))

