from pathlib import Path
import re, unittest
ROOT=Path(__file__).parent
def broken(root):
    errors=[]
    for path in [root/'README.md',*(root/'reference').glob('*.md')]:
        for target in re.findall(r'\]\(([^)]+)\)',path.read_text()):
            if not (path.parent/target).exists(): errors.append((path,target))
    return errors
class Links(unittest.TestCase):
    def test_links(self): self.assertEqual(broken(ROOT),[])
if __name__ == '__main__': unittest.main()

